TITLE = ParagraphStyle("title", fontName="DVB", fontSize=16, leading=20, spaceAfter=8)
HEADING = ParagraphStyle("heading", fontName="DVB", fontSize=10.5, leading=14, spaceBefore=8, spaceAfter=4)
BODY = ParagraphStyle("body", fontName="DV", fontSize=9.5, leading=14)
SMALL = ParagraphStyle("small", fontName="DV", fontSize=8.5, leading=12, textColor=colors.HexColor("#5f6b7a"))

for row in INCIDENTS:
    (incident_id, rule, operation_time, store, cash, product, barcode, article, marking_code,
     violation_type, result, source_kind, source_text, reason, verification_source) = row
    doc = SimpleDocTemplate(
        str(OUT / f"{incident_id}.pdf"), pagesize=A4,
        rightMargin=18 * mm, leftMargin=18 * mm, topMargin=16 * mm, bottomMargin=16 * mm,
        title=f"Описание инцидента {incident_id}",
    )
    story = [
        Paragraph(f"Описание инцидента {incident_id}", TITLE),
        Paragraph("Документ сформирован для пояснения обстоятельств инцидента контролирующим органам.", SMALL),
        Spacer(1, 5 * mm),
    ]
    fields = [
        ("Правило", rule), ("Дата и время операции", operation_time), ("Магазин", store), ("Касса", cash),
        ("Товар", product), ("Штрихкод", barcode), ("Артикул", article), ("Полный код маркировки", marking_code),
        ("Тип нарушения", violation_type), ("Результат проверки", result), ("Источник проверки", verification_source),
    ]
    table = Table([[Paragraph(a, SMALL), Paragraph(b, BODY)] for a, b in fields], colWidths=[45 * mm, 115 * mm])
    table.setStyle(TableStyle([
        ("VALIGN", (0, 0), (-1, -1), "TOP"),
        ("LINEBELOW", (0, 0), (-1, -1), 0.25, colors.HexColor("#e1e5ea")),
        ("LEFTPADDING", (0, 0), (-1, -1), 4), ("RIGHTPADDING", (0, 0), (-1, -1), 4),
        ("TOPPADDING", (0, 0), (-1, -1), 5), ("BOTTOMPADDING", (0, 0), (-1, -1), 5),
    ]))
    story.extend([
        table,
        Paragraph("Исходное отклонение", HEADING), Paragraph(source_kind, BODY), Paragraph(source_text, BODY),
        Paragraph("Результат анализа", HEADING), Paragraph(reason, BODY), Spacer(1, 5 * mm),
        Paragraph("Документ не содержит сведений о назначенном штрафе, потенциальной сумме штрафа, рекомендаций по устранению или подписи.", SMALL),
    ])
    doc.build(story)

print(f"Generated {len(INCIDENTS)} incident PDFs in {OUT}")
